   236|export async function handleIVXOwnerPasswordlessLogin(request: Request): Promise<Response> {
   237|  if (request.method !== 'POST') {
   238|    return ownerOnlyJson({ success: false, message: 'Method not allowed.', deploymentMarker: DEPLOYMENT_MARKER }, 405);
   239|  }
   240|
   241|  let body: Record<string, unknown> = {};
   242|  try {
   243|    body = (await request.json().catch(() => ({}))) as Record<string, unknown>;
   244|  } catch {
   245|    body = {};
   246|  }
   247|  const email = sanitizeEmail(body.email);
   248|
   249|  // EMERGENCY-ONLY GATE: passwordless login is restricted to emergency recovery.
   250|  // The owner must use standard email + password sign-in for routine access.
   251|  // This endpoint is kept as a last-resort lockout recovery path only.
   252|  const emergency = readTrimmed(body.emergency).toLowerCase();
   253|  if (emergency !== 'true' && emergency !== 'ivx_emergency_recovery') {
   254|    const failure: OwnerSessionFailure = {
   255|      success: false,
   256|      message: 'Passwordless owner login is emergency-only. Please sign in with your email and password. If you are locked out, include { "emergency": "ivx_emergency_recovery" } in the request body.',
   257|      rootCause: 'passwordless_not_emergency_mode',
   258|      deploymentMarker: DEPLOYMENT_MARKER,
   259|      timestamp: nowIso(),
   260|    };
   261|    return ownerOnlyJson(failure, 403);
   262|  }
   263|
   264|  if (!isValidEmail(email)) {
   265|    const failure: OwnerSessionFailure = {
   266|      success: false,
   267|      message: 'A valid owner email is required.',
   268|      rootCause: 'missing_or_invalid_email',
   269|      deploymentMarker: DEPLOYMENT_MARKER,
   270|      timestamp: nowIso(),
   271|    };
   272|    return ownerOnlyJson(failure, 400);
   273|  }
   274|
   275|  const allowlist = getIVXOwnerEmailAllowlist();
   276|  if (!allowlist.includes(email)) {
   277|    const failure: OwnerSessionFailure = {
   278|      success: false,
   279|      message: 'This email is not on the owner allowlist. Owner login is restricted to the configured owner.',
   280|      rootCause: 'email_not_allowlisted',
   281|      deploymentMarker: DEPLOYMENT_MARKER,
   282|      timestamp: nowIso(),
   283|    };
   284|    return ownerOnlyJson(failure, 403);
   285|  }
   286|
   287|  const supabaseUrl = resolveSupabaseUrl();
   288|  if (!supabaseUrl) {
   289|    const failure: OwnerSessionFailure = {
   290|      success: false,
   291|      message: 'Supabase URL is not configured on the backend.',
   292|      rootCause: 'supabase_url_not_configured',
   293|      deploymentMarker: DEPLOYMENT_MARKER,
   294|      timestamp: nowIso(),
   295|    };
   296|    return ownerOnlyJson(failure, 500);
   297|  }
   298|
   299|  let adminClient: SupabaseClient;
   300|  try {
   301|    adminClient = createAdminClient();
   302|  } catch (error) {
   303|    const failure: OwnerSessionFailure = {
   304|      success: false,
   305|      message: error instanceof Error ? error.message : 'Failed to initialize Supabase admin client.',
   306|      rootCause: 'admin_client_init_failed',
   307|      deploymentMarker: DEPLOYMENT_MARKER,
   308|      timestamp: nowIso(),
   309|    };
   310|    return ownerOnlyJson(failure, 500);
   311|  }
   312|
   313|  // Locate the owner auth user (list + match by email).
   314|  let authUserId: string | null = null;
   315|  let authUserCreated = false;
   316|  try {
   317|    const { data: listData, error: listError } = await adminClient.auth.admin.listUsers({ page: 1, perPage: 1000 });
   318|    if (listError) {
   319|      const failure: OwnerSessionFailure = {
   320|        success: false,
   321|        message: `Supabase admin listUsers failed: ${listError.message}`,
   322|        rootCause: 'admin_list_users_failed',
   323|        deploymentMarker: DEPLOYMENT_MARKER,
   324|        timestamp: nowIso(),
   325|      };
   326|      return ownerOnlyJson(failure, 502);
   327|    }
   328|    const users = Array.isArray(listData?.users) ? listData.users : [];
   329|    const match = users.find((u) => sanitizeEmail(u.email) === email);
   330|    authUserId = match?.id ?? null;
   331|  } catch (error) {
   332|    const failure: OwnerSessionFailure = {
   333|      success: false,
   334|      message: error instanceof Error ? error.message : 'Failed to list Supabase auth users.',
   335|      rootCause: 'admin_list_users_threw',
   336|      deploymentMarker: DEPLOYMENT_MARKER,
   337|      timestamp: nowIso(),
   338|    };
   339|    return ownerOnlyJson(failure, 502);
   340|  }
   341|
   342|  if (!authUserId) {
   343|    // Create the owner auth user with a random password + confirmed email.
   344|    // The random password is never disclosed; the owner sets their real
   345|    // password via owner-access-repair or "Forgot" flows.
   346|    try {
   347|      const { data, error } = await adminClient.auth.admin.createUser({
   348|        email,
   349|        password: readEnv('IVX_OWNER_PASSWORD') || generateRandomPassword(),
   350|        email_confirm: true,
   351|        user_metadata: {
   352|          accountType: 'owner',
   353|          requestedRole: 'owner',
   354|          role: 'owner',
   355|          status: 'active',
   356|          kycStatus: 'approved',
   357|        },
   358|        app_metadata: {
   359|          accountType: 'owner',
   360|          requestedRole: 'owner',
   361|          role: 'owner',
   362|        },
   363|      });
   364|      if (error || !data.user) {
   365|        const failure: OwnerSessionFailure = {
   366|          success: false,
   367|          message: error?.message ?? 'Supabase did not return a created owner user.',
   368|          rootCause: 'admin_create_user_failed',
   369|          deploymentMarker: DEPLOYMENT_MARKER,
   370|          timestamp: nowIso(),
   371|        };
   372|        return ownerOnlyJson(failure, 502);
   373|      }
   374|      authUserId = data.user.id;
   375|      authUserCreated = true;
   376|    } catch (error) {
   377|      const failure: OwnerSessionFailure = {
   378|        success: false,
   379|        message: error instanceof Error ? error.message : 'Failed to create owner auth user.',
   380|        rootCause: 'admin_create_user_threw',
   381|        deploymentMarker: DEPLOYMENT_MARKER,
   382|        timestamp: nowIso(),
   383|      };
   384|      return ownerOnlyJson(failure, 502);
   385|    }
   386|  } else {
   387|    // Make sure the existing owner user is confirmed and not banned —
   388|    // WITHOUT changing their password.
   389|    try {
   390|      await adminClient.auth.admin.updateUserById(authUserId, {
   391|        email_confirm: true,
   392|        ban_duration: 'none',
   393|      });
   394|    } catch {
   395|      // Non-fatal: the magic-link mint below will surface any real blocker.
   396|    }
   397|  }
   398|
   399|  // PRIMARY PATH — mint a session with a magic-link token. Password untouched.
   400|  const minted = await mintSessionViaMagicLink(adminClient, email);
   401|  if (minted.ok && minted.session) {
   402|    const expiresAt = minted.session.expiresAt;
   403|    const successPayload: OwnerSessionResponse = {
   404|      success: true,
   405|      accessToken: minted.session.accessToken,
   406|      refreshToken: minted.session.refreshToken,
   407|      expiresAt,
   408|      expiresAtIso: expiresAt ? new Date(expiresAt * 1000).toISOString() : nowIso(),
   409|      userId: authUserId,
   410|      email,
   411|      passwordSelfHealed: false,
   412|      passwordPreserved: true,
   413|      sessionMethod: 'magiclink_token_hash',
   414|      authUserCreated,
   415|      deploymentMarker: DEPLOYMENT_MARKER,
   416|      timestamp: nowIso(),
   417|    };
   418|    return ownerOnlyJson(successPayload as unknown as Record<string, unknown>);
   419|  }
   420|
   421|  // LEGACY FALLBACK — only if the magic-link mint failed. This is the old
   422|  // self-heal behavior (resets the password), kept strictly as a last resort
   423|  // so the owner can never be locked out entirely.
   424|  const ownerPassword = readEnv('IVX_OWNER_PASSWORD') || generateRandomPassword();
   425|  let passwordSelfHealed = false;
   426|  try {
   427|    const { error: updateError } = await adminClient.auth.admin.updateUserById(authUserId, {
   428|      password: ownerPassword,
   429|      email_confirm: true,
   430|      ban_duration: 'none',
   431|    });
   432|    if (updateError) {
   433|      const failure: OwnerSessionFailure = {
   434|        success: false,
   435|        message: `Magic-link session mint failed (${minted.errorMessage ?? 'unknown'}) and fallback password reset failed: ${updateError.message}`,
   436|        rootCause: 'fallback_password_reset_failed',
   437|        deploymentMarker: DEPLOYMENT_MARKER,
   438|        timestamp: nowIso(),
   439|      };
   440|      return ownerOnlyJson(failure, 502);
   441|    }
   442|    passwordSelfHealed = true;
   443|  } catch (error) {
   444|    const failure: OwnerSessionFailure = {
   445|      success: false,
   446|      message: error instanceof Error ? error.message : 'Fallback password reset threw.',
   447|      rootCause: 'fallback_password_reset_threw',
   448|      deploymentMarker: DEPLOYMENT_MARKER,
   449|      timestamp: nowIso(),
   450|    };
   451|    return ownerOnlyJson(failure, 502);
   452|  }
   453|
   454|  const grant = await passwordGrant(supabaseUrl, email, ownerPassword);
   455|  if (!grant.ok || !grant.accessToken || !grant.refreshToken) {
   456|    const failure: OwnerSessionFailure = {
   457|      success: false,
   458|      message: grant.errorMessage ?? 'Password grant failed.',
