   469|    accessToken: grant.accessToken,
   470|    refreshToken: grant.refreshToken,
   471|    expiresAt,
   472|    expiresAtIso: expiresAt ? new Date(expiresAt * 1000).toISOString() : nowIso(),
   473|    userId: authUserId,
   474|    email,
   475|    passwordSelfHealed,
